def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves.

    Recurses only where both values are dicts; treats all other values (including
    lists) atomically. If a key is added or removed entirely, only the parent path
    is returned (no descent into the added/removed subtree).
    """
    if not (isinstance(before, dict) and isinstance(after, dict)):
        return []

    result = []
    before_keys = set(before)
    after_keys = set(after)

    for key in before_keys - after_keys:
        result.append(key)

    for key in after_keys - before_keys:
        result.append(key)

    for key in before_keys & after_keys:
        bv = before[key]
        av = after[key]
        if isinstance(bv, dict) and isinstance(av, dict):
            for sub in changed_paths(bv, av):
                result.append(f"{key}.{sub}")
        else:
            if bv != av:
                result.append(key)

    return sorted(result)
```

