def coalesce(intervals):
    """Merge overlapping or touching half-open integer intervals (start, end).

    - Discards empty intervals where start == end.
    - Raises ValueError if any interval has start > end.
    - Returns a new sorted list of tuples; does not mutate the input.
    """
    cleaned = []
    for start, end in intervals:
        if start > end:
            raise ValueError(f"Interval start {start} is greater than end {end}")
        if start < end:
            cleaned.append((start, end))

    cleaned.sort()

    if not cleaned:
        return []

    merged = [cleaned[0]]
    for start, end in cleaned[1:]:
        if start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))

    return merged
