def frames(lines):
    results = []
    data_parts = []

    for line in lines:
        if line == "":
            results.append("\n".join(data_parts))
            data_parts = []
        elif line.startswith(":"):
            continue
        else:
            idx = line.find(":")
            if idx == -1:
                name, value = line, ""
            else:
                name = line[:idx]
                value = line[idx + 1:]
                if value.startswith(" "):
                    value = value[1:]
            if name == "data":
                data_parts.append(value)

    return results
