def unique_latest(records):
    best = {}
    order = []
    for record in records:
        rid = record['id']
        if rid not in best:
            order.append(rid)
        if rid not in best or record['timestamp'] >= best[rid]['timestamp']:
            best[rid] = record
    return [best[rid] for rid in order]
