def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    Rules:
      - Must start with '/' or ValueError is raised.
      - Collapses redundant slashes.
      - Removes '.' components.
      - Resolves '..' without going above root.
      - Returns '/' for the root; no trailing slash otherwise.
    """
    if not path.startswith('/'):
        raise ValueError(f"not an absolute path: {path!r}")

    stack: list[str] = []
    for part in path.split('/'):
        if part in ('', '.'):
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    if not stack:
        return '/'
    return '/' + '/'.join(stack)
```

