def pack(items, max_bytes):
    """Greedily pack consecutive items into batches whose UTF-8 byte length sum <= max_bytes."""
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")

    if not items:
        return []

    byte_lengths = [len(s.encode('utf-8')) for s in items]

    for i, bl in enumerate(byte_lengths):
        if bl > max_bytes:
            raise ValueError(
                f"item at index {i} has UTF-8 byte length {bl} exceeding max_bytes {max_bytes}"
            )

    result = []
    current_batch = []
    current_sum = 0

    for item, bl in zip(items, byte_lengths):
        if current_sum + bl <= max_bytes:
            current_batch.append(item)
            current_sum += bl
        else:
            result.append(current_batch)
            current_batch = [item]
            current_sum = bl

    if current_batch:
        result.append(current_batch)

    return result
