import heapq


def order(deps):
    nodes = set(deps.keys())
    for prereqs in deps.values():
        nodes.update(prereqs)

    prereqs = {node: set(deps.get(node, [])) for node in nodes}

    dependents = {node: set() for node in nodes}
    for node in nodes:
        for p in prereqs[node]:
            dependents[p].add(node)

    in_degree = {node: len(prereqs[node]) for node in nodes}

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dep in dependents[node]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                heapq.heappush(heap, dep)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
```

