def redact(value, sensitive):
    """Recursively copy a JSON-like structure, redacting sensitive keys.

    Args:
        value: A dict, list, or scalar (str, int, float, bool, None).
        sensitive: Iterable of strings; matching is case-insensitive and exact.

    Returns:
        A new structure with sensitive dictionary values replaced by "[REDACTED]".
    """
    sensitive_lower = {s.lower() for s in sensitive}
    return _redact(value, sensitive_lower)


def _redact(value, sensitive_lower):
    if isinstance(value, dict):
        return {
            key: (
                "[REDACTED]"
                if isinstance(key, str) and key.lower() in sensitive_lower
                else _redact(val, sensitive_lower)
            )
            for key, val in value.items()
        }
    if isinstance(value, list):
        return [_redact(item, sensitive_lower) for item in value]
    return value
